tp_dist = tp_dollars / pv

vma = ta.ema(volume * close, vwma_len) / ta.ema(volume, vwma_len)
rsi = ta.rsi(close, rsi_len)

// Structure: Higher Highs / Lower Lows
hh = ta.highest(high, lookback)
ll = ta.lowest(low, lookback)

// BOS Logic: Break of Structure
// Long BOS: Price breaks above previous high (hh) and RSI is not overbought
// Short BOS: Price breaks below previous low (ll) and RSI is not oversold
long_bos = ta.crossover(close, hh[1]) and rsi < 70
short_bos = ta.crossunder(close, ll[1]) and rsi > 30

// VWMA Trend Filter
// Only take longs if price is above VWMA, shorts if below
long_trend = close > vma
short_trend = close < vma

atr = ta.atr(atr_len)
rsi = ta.rsi(close, rsi_len)
ema_f = ta.ema(close, ema_fast)
ema_s = ta.ema(close, ema_slow)

// Structure: Higher High / Lower Low
