    last_high := pivot_high
if not na(pivot_low)
    last_low := pivot_low

// BOS Conditions
long_bos = close > last_high[1] and not na(last_high)
short_bos = close < last_low[1] and not na(last_low)

// RSI Reversal Conditions
// Long: RSI oversold (<30) and rising, or crossing above 30
long_rsi_cond = ta.crossover(rsi_val, 30)
// Short: RSI overbought (>70) and falling, or crossing below 70
short_rsi_cond = ta.crossunder(rsi_val, 70)

// Trend Filter: Price above VWMA for longs, below for shorts
long_trend = close > trend
short_trend = close < trend

// Entry Conditions
