trendUp = ta.crossover(emaFast, emaSlow) or (emaFast > emaSlow and ta.rising(emaFast, 3))
trendDown = ta.crossunder(emaFast, emaSlow) or (emaFast < emaSlow and ta.falling(emaFast, 3))

// Condition 2: RSI Momentum Filter
// Long: RSI crosses above 40 (oversold bounce) or RSI > 50 and rising
// Short: RSI crosses below 60 (overbought drop) or RSI < 50 and falling
rsiCrossUp = ta.crossover(rsi, 40)
rsiCrossDown = ta.crossunder(rsi, 60)

ema_fast = ta.ema(close, 20)
ema_slow = ta.ema(close, 55)
atr_val = ta.atr(atr_len)

// Structure: Higher Highs and Higher Lows (BOS)
hh = ta.highest(high, lookback)
lh = ta.lowest(low, lookback)
// Simple BOS detection: Close breaks previous local extreme
// Using a simplified logic for robustness: Price > HH of lookback (Long BOS) or < LL (Short BOS)
is_long_bos = close > hh
is_short_bos = close < lh

// Momentum Filter: Trend alignment
trend_up = ta.rising(close, 10) and ta.crossover(ema_fast, ema_slow)
trend_down = ta.falling(close, 10) and ta.crossunder(ema_fast, ema_slow)

ema = ta.ema(close, ema_len)
pivot_high = ta.pivothigh(high, pivot_left, pivot_right)
pivot_low = ta.pivotlow(low, pivot_left, pivot_right)

// Store pivot values when they form
