var float last_low_price = na
var int last_high_bar = na
var int last_low_bar = na

if not na(pivot_high)
    last_high_price := pivot_high
    last_high_bar := bar_index
if not na(pivot_low)
    last_low_price := pivot_low
    last_low_bar := bar_index

// Check if price broke structure relative to last pivot
// Long: Price breaks above last high pivot AND closes above EMA
// Short: Price breaks below last low pivot AND closes below EMA
long_condition = not na(last_high_price) and close > last_high_price and close > ema
short_condition = not na(last_low_price) and close < last_low_price and close < ema

ema_trend = ta.ema(close, len_ema)
vma = ta.vwma(close, len_vwma)
atr_val = ta.atr(len_atr)

// Structure: Higher Lows (BOS)
left = 5
right = 5
pivot_low = ta.pivotlow(low, left, right)
pivot_high = ta.pivothigh(high, left, right)

// Trend Filter: Price above EMA and VWMA rising
trend_up = close > ema_trend and ta.rising(vma, 5)
trend_down = close < ema_trend and ta.falling(vma, 5)

// Trigger: Break of Structure after Pullback
// Long: Price breaks above previous pivot high after being below it (pullback)
// Short: Price breaks below previous pivot low after being above it (pullback)

var int last_entry_bar = -999
var string last_entry = ""

// Cooldown check
can_trade = (bar_index - last_entry_bar) >= cooldown_bars

// Long Setup
long_cond = trend_up and can_trade and not na(pivot_low)
// We need a pivot high to break. Check if we recently broke a pivot high or are approaching one.
// Simplified: Enter long if price crosses above a recent pivot high while in uptrend.
// Since pivot_high is known rightbars later, we check if close > ta.valuewhen(ta.pivothigh(high, left, right), high, 1)
// However, to avoid repainting issues in strategy, we use the confirmed pivot.
// Let's use a simpler BOS: Close > Highest High of last N bars.
highest_high = ta.highest(high, 20)
lowest_low = ta.lowest(low, 20)

long_entry = trend_up and close > highest_high[1] and close > ta.valuewhen(ta.pivothigh(high, left, right), high, 1) and can_trade
short_entry = trend_down and close < lowest_low[1] and close < ta.valuewhen(ta.pivotlow(low, left, right), low, 1) and can_trade

ema_fast = ta.ema(close, ema_fast_len)
ema_slow = ta.ema(close, ema_slow_len)
rsi = ta.rsi(close, rsi_len)
atr = ta.atr(atr_len)

// Structure: EMA crossover + RSI momentum shift
// Long: Fast EMA crosses above Slow EMA, RSI < 50 (oversold pullback) or RSI rising
// Short: Fast EMA crosses below Slow EMA, RSI > 50 (overbought pullback) or RSI falling
// We use a momentum shift filter to avoid chop.

// Condition 1: Trend/Structure Filter
// We look for a shift in momentum rather than just a cross.
// RSI crossing 50 is a common threshold, but we want to catch the shift.
// Let's use RSI crossing its own SMA or just crossing 50 with direction.
// To keep it simple and robust: RSI > 50 for longs, RSI < 50 for shorts, combined with EMA cross.
// However, the "Shift" implies a change in direction.
// Let's use: EMA Cross + RSI not at extreme (e.g., not > 80 or < 20) to avoid late entries.

// Better: Use the "Shift" idea from the library.
// Long: EMA Fast crosses above EMA Slow. RSI must be rising (ta.rising) or just crossed 50 from below.
// Let's use ta.crossover(close, ta.sma(close, 10)) as a proxy for momentum shift? No, use RSI.
// ta.crossover(rsi, 50) is a strong signal.

// Condition 2: Trigger
// We need at least two agreeing conditions.
// 1. EMA Cross (Trend)
// 2. RSI Cross 50 (Momentum Shift)

bool ema_cross_up = ta.crossover(ema_fast, ema_slow)
bool ema_cross_down = ta.crossunder(ema_fast, ema_slow)

bool rsi_cross_up = ta.crossover(rsi, 50)
bool rsi_cross_down = ta.crossunder(rsi, 50)

// Cooldown logic
var int last_entry_bar = na
var bool in_cooldown = false

if in_cooldown
    if bar_index - last_entry_bar >= cooldown_bars
        in_cooldown := false
    else
        in_cooldown := true // Stay in cooldown

// Session Filter: Guideline 1

// Entries
if in_cooldown == false and in_session
    if ema_cross_up and rsi_cross_up
        strategy.entry("Long", strategy.long)
        last_entry_bar := bar_index
        in_cooldown := true
    if ema_cross_down and rsi_cross_down
        strategy.entry("Short", strategy.short)
        last_entry_bar := bar_index
        in_cooldown := true

// Exit Logic: Fixed Prices
// Long Exit
if strategy.position_size > 0
    stop_price_long = close - stop_dollars / pv
    tp_price_long = close + tp_dollars / pv
    strategy.exit("Long", "Long", stop=stop_price_long, limit=tp_price_long)

// Short Exit
if strategy.position_size < 0
    stop_price_short = close + stop_dollars / pv
    tp_price_short = close - tp_dollars / pv
    strategy.exit("Short", "Short", stop=stop_price_short, limit=tp_price_short)

// Guideline 1: Flatten every open trade at 16:45 New York

vwma = ta.vwma(close, vwma_len)
sma = ta.sma(close, sma_len)
atr = ta.atr(atr_len)

// Structure: Higher Highs / Lower Lows
hh = ta.pivothigh(high, pivot_left, pivot_right)
ll = ta.pivotlow(low, pivot_left, pivot_right)

// BOS Logic: Price closes above a previous high (for longs) or below a previous low (for shorts)
// We use ta.valuewhen to get the last pivot high/low price
last_high = ta.valuewhen(not na(hh), high, 1)
last_low = ta.valuewhen(not na(ll), low, 1)

// Trend Filter: VWMA > SMA for longs, VWMA < SMA for shorts
trend_long = vwma > sma
trend_short = vwma < sma

ema = ta.ema(close, ema_len)
pivot_high = ta.pivothigh(high, pivot_left, pivot_right)
pivot_low = ta.pivotlow(low, pivot_left, pivot_right)

// Store pivot values when they form
var float last_high_price = na
var float last_low_price = na
var int last_high_bar = na
var int last_low_bar = na

// Check if price broke structure relative to last pivot
// Long: Price breaks above last high pivot AND closes above EMA
// Short: Price breaks below last low pivot AND closes below EMA
long_condition = not na(last_high_price) and close > last_high_price and close > ema
short_condition = not na(last_low_price) and close < last_low_price and close < ema

ema_val = ta.ema(close, ema_len)
ema_slope = (ema_val - ema_val[ema_slope_len]) / ema_slope_len
bool ema_up = ema_slope > min_slope
bool ema_dn = ema_slope < -min_slope

// Simple RSI for entry trigger
rsi_len = 14
rsi_val = ta.rsi(close, rsi_len)

// Entry Logic: Replace complex AI score with RSI extremes aligned with trend
// Long: Trend Up (EMA slope > min_slope) AND RSI < 30 (Oversold)
// Short: Trend Down (EMA slope < -min_slope) AND RSI > 70 (Overbought)
bool long_ok = in_session and ema_up and rsi_val < 30 and strategy.position_size == 0
bool short_ok = in_session and ema_dn and rsi_val > 70 and strategy.position_size == 0

// Flatten at 16:45 New York
bool flatten_time = bar_hr == 16 and bar_mn >= 45
if flatten_time and strategy.position_size != 0
    strategy.close_all(comment="EOD Flatten")

indicators.source:
var int trend = 0
if ta.crossover(fast_ma, slow_ma)
    trend := 1
if ta.crossunder(fast_ma, slow_ma)
    trend := -1

float prior_poc_h = poc_hi[prior_poc_bars]
float prior_poc_l = poc_lo[prior_poc_bars]
bool  prior_poc_ok = not na(prior_poc_h) and not na(prior_poc_l) and atr_ok

// Prior POC must be distinctly different from the current POC (at least 0.5 ATR apart)
bool pocs_distinct = prior_poc_ok and poc_valid and math.abs(nz(poc_price) - (prior_poc_h + prior_poc_l) / 2) > atr_risk * 0.5

// SHORT blocked: prior POC HIGH edge is below entry → support floor within ATR range
bool support_blocks_short = pocs_distinct and prior_poc_h < close and (close - prior_poc_h) < opposing_atr_mult * atr_risk

// LONG blocked: prior POC LOW edge is above entry → resistance ceiling within ATR range
bool resist_blocks_long = pocs_distinct and prior_poc_l > close and (prior_poc_l - close) < opposing_atr_mult * atr_risk

bool opposing_ok_long  = not use_opposing_poc or not resist_blocks_long
bool opposing_ok_short = not use_opposing_poc or not support_blocks_short

// Cooldown + flat
var int last_trade_bar = -9999
bool cooled  = bar_index - last_trade_bar >= cooldown_bars
bool is_flat = strategy.position_size == 0 and (na(strategy.position_size[1]) or strategy.position_size[1] == 0)

// LONG:  green POC + higher lows + no opposing resistance + VWMA slope + EMA trend + pullback + bullish close
// SHORT: red POC + lower highs + no opposing support + VWMA slope + EMA trend + rally + bearish close
bool long_sig  = depth_ok_long  and poc_green and pivot_ok_long  and opposing_ok_long  and slope_ok_long  and ema_ok_long  and bullish_candle and in_session and cooled and is_flat
bool short_sig = depth_ok_short and poc_red   and pivot_ok_short and opposing_ok_short and slope_ok_short and ema_ok_short and bearish_candle and in_session and cooled and is_flat

